sheet({title:'Stinger', units:'in'})

// Robots must fit inside the 18 x 18 x 18 box during initialization: 
// corner at x=0, y=0, z=0; 18 along x, 18 along y, 18 tall
box(-9,-9,0, 18,18,18, {fill:C.white, alpha:0.15, limit:true})

// Variables
const W=17, L=17.5          // frame outside width (x) and length (y)
const T=2.76, H=4.5, Z0=1  // rail thickness, rail height, bottom of the rails above the tiles


                          // Chassis
// Frame
for (const x of [-8.06, 5.11]){
  box(x, -8.7,0, T, L, H, {fill: C.alu}) // Left and Right vertical frame for the wheels
}

for (const y of [-0.945, 6]){
  box(-5.3, y, 1.81, 10.39, 1.89, 0.47, {fill: C.alu})// back and middle horizontal frame to hold the vertical frames together
}

// Wheels
for (const x of [-7.43, 5.74]){ // -8.06+0.63 and 5.11+0.63: wheel starts 0.63 in from each pod's left face
  for (const y of [-6.61, 6.61]){ // 8.5-1.89: axle so the tread ends flush with the pod ends
    cyl(x, y, 2.05, 2.05, 1.5, {axis: 'x', fill: C.dark})
  }
}

// Dimensioning
dim([-8.06,-8.5,H], [-8.06,-8.5+L,H], {off:40, text:`${L}" Chassis length`})
dim([-8.06,-8.5,H], [-5.3,-8.5,H], {off:40, text:`${T}" Chassis width`})
